dry = "--apply" not in sys.argv
ok = fail = 0
for slug, fixes in FIXES.items():
    p = next(POSTS.glob(slug + ".ts"), None)
    if p is None:
        print("!! нет файла " + slug); fail += 1; continue
    src = p.read_text(encoding="utf-8")
    for old, new in fixes:
        if old not in src:
            print("!! fix не найден в " + slug + ": " + old[:40]); fail += 1; continue
        src = src.replace(old, new)
    if src != p.read_text(encoding="utf-8") and not dry:
        p.write_text(src, encoding="utf-8")
    ok += 1

for slug, ins in INSERT.items():
    p = next(POSTS.glob(slug + ".ts"), None)
    if p is None:
        print("!! нет файла " + slug); fail += 1; continue
    src = p.read_text(encoding="utf-8")
    if MARK not in src:
        print("!! маркер не найден: " + slug); fail += 1; continue
    src = src.replace(MARK, ins.strip("\n") + "\n\n" + MARK, 1)
    if not dry:
        p.write_text(src, encoding="utf-8")
    ok += 1

print(f"итог: {ok} операций, {fail} проблем" + (" (dry-run)" if dry else ""))
